&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Analyze&amp;nbsp;manufacturing&amp;nbsp;processes and machinery from a first principles, physics-based approach&amp;nbsp;with focus on&amp;nbsp;mechanical domain&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with taking products from&amp;nbsp;concept&amp;nbsp;and development into&amp;nbsp;high-volume&amp;nbsp;production&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with manufacturing processes like&amp;nbsp;casting,&amp;nbsp;injection molding,&amp;nbsp;stamping,&amp;nbsp;extrusion,&amp;nbsp;lamination, die cutting, etc.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Research and identify new materials, manufacturing technologies, and finish options&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Develop&amp;nbsp;part qualification&amp;nbsp;criteria, collaborate on&amp;nbsp;functional&amp;nbsp;and reliability&amp;nbsp;requirements, and drive system-level optimization for&amp;nbsp;high-volume production.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Lead Design of Experiments (DOE)&amp;nbsp;to&amp;nbsp;develop&amp;nbsp;supplier&amp;nbsp;production&amp;nbsp;processes&amp;nbsp;for high-rate, high-yield, and reliable&amp;nbsp;parts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Perform&amp;nbsp;defect characterization and analysis to determine root cause to improve&amp;nbsp;manufacturing&amp;nbsp;yields&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Review DFM from the supplier, including&amp;nbsp;process flow, in-line metrology, inspection mechanism, and&amp;nbsp;engineering analysis&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Direct&amp;nbsp;the supplier process&amp;nbsp;modifications while ultimately responsible for approving first article inspection (FAI) reports, and Production Part Approval Process (PPAP) reports&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Collaborate with design, materials, and manufacturing engineers to gain an in-depth knowledge of&amp;nbsp;mechanical parts, assembly, metrology, and&amp;nbsp;sub-system design intent&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Support the procurement team to strategically source parts matched with supplier competencies by reviewing and assessing supplier manufacturing processes and quality systems&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Create and define supplier technical and quality requirements based on NPI&amp;nbsp;lifecycle,&amp;nbsp;production phases, and program requirement&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Demonstrate a strong sense of ownership, proactivity, technical excellence, creativity, self-direction, and courage&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
